import 'package:cloud_firestore/cloud_firestore.dart';

// One chat message stored under
// chat_rooms/{chatRoomId}/messages/{autoGeneratedId}
// (Lab Activity 6 - Firebase Part II).
class HusseinAdvmobprogMessage {
  final String senderId;
  final String senderEmail;
  final String receiverId;
  final String message;
  final Timestamp timestamp;

  // True once the receiver has opened the conversation. New messages are
  // always written as false; documents stored before this field existed
  // read as true, so older chats never show a stale unread badge.
  final bool isRead;

  HusseinAdvmobprogMessage({
    required this.senderId,
    required this.senderEmail,
    required this.receiverId,
    required this.message,
    required this.timestamp,
    this.isRead = false,
  });

  // Reads a Firestore map defensively: missing or broken fields fall
  // back to harmless defaults so one bad document can never crash the
  // chat screen.
  factory HusseinAdvmobprogMessage.fromMap(Map<String, dynamic> map) {
    return HusseinAdvmobprogMessage(
      senderId: map['senderId']?.toString() ?? '',
      senderEmail: map['senderEmail']?.toString() ?? '',
      receiverId: map['receiverId']?.toString() ?? '',
      message: map['message']?.toString() ?? '',
      timestamp: _readTimestamp(map['timestamp']),
      isRead: map['isRead'] != false,
    );
  }

  Map<String, dynamic> toMap() {
    return {
      'senderId': senderId,
      'senderEmail': senderEmail,
      'receiverId': receiverId,
      'message': message,
      'timestamp': timestamp,
      'isRead': isRead,
    };
  }

  // Accepts a Firestore Timestamp, a DateTime or epoch milliseconds.
  // Anything else (null right after a local write, for example) falls
  // back to "now" so a timestamp can always be rendered safely.
  static Timestamp _readTimestamp(dynamic value) {
    if (value is Timestamp) return value;
    if (value is DateTime) return Timestamp.fromDate(value);
    if (value is num) {
      return Timestamp.fromMillisecondsSinceEpoch(value.toInt());
    }

    return Timestamp.now();
  }
}
